import React, { useState, FormEvent } from 'react';
import {
  Form,
  FormField,
  Label,
  TextInput,
  Select,
  SelectOption,
  Switch,
  Button,
} from '@jinx-ui/react';

type Language = 'ru' | 'en';

interface ProfileSettings {
  name: string;
  language: Language;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
  initialName?: string;
  initialLanguage?: Language;
  initialEmailNotifications?: boolean;
}

const ProfileSettingsForm: React.FC<ProfileSettingsFormProps> = ({
  onSave,
  initialName = '',
  initialLanguage = 'ru',
  initialEmailNotifications = true,
}) => {
  const [name, setName] = useState(initialName);
  const [language, setLanguage] = useState<Language>(initialLanguage);
  const [emailNotifications, setEmailNotifications] = useState(
    initialEmailNotifications
  );

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <Form
      className="jx-stack jx-stack--md"
      style={{ maxWidth: 'var(--jx-size-form-md, 420px)' }}
      onSubmit={handleSubmit}
    >
      <FormField>
        <Label htmlFor="profile-name">Имя</Label>
        <TextInput
          id="profile-name"
          name="name"
          value={name}
          placeholder="Введите имя"
          onChange={(event) => setName(event.target.value)}
        />
      </FormField>

      <FormField>
        <Label htmlFor="profile-language">Язык интерфейса</Label>
        <Select
          id="profile-language"
          name="language"
          value={language}
          onChange={(value) => setLanguage(value as Language)}
        >
          <SelectOption value="ru">Русский</SelectOption>
          <SelectOption value="en">Английский</SelectOption>
        </Select>
      </FormField>

      <FormField className="jx-row jx-row--between jx-row--align-center">
        <Label htmlFor="profile-email-notifications">
          Уведомления на почту
        </Label>
        <Switch
          id="profile-email-notifications"
          name="emailNotifications"
          checked={emailNotifications}
          onChange={(checked) => setEmailNotifications(checked)}
        />
      </FormField>

      <Button type="submit" variant="primary">
        Сохранить
      </Button>
    </Form>
  );
};

export default ProfileSettingsForm;

